def check_conditions(u, v):
    """
    Checks if for a given (u, v), the 2v conditions are met.
    Conditions: f(u+v+k) - f(u+k) is a multiple of 4 for k=0 to 2v-1.
    """
    for k in range(2 * v):
        # Check f(u+v+k) - f(u+k) mod 4 == 0
        diff = f(u + v + k) - f(u + k)
        if diff % 4 != 0:
            return False
    return True

