def f(n):
    """Calculates the largest odd divisor of n."""
    while n > 0 and n % 2 == 0:
        n //= 2
    return n

# Test f(n+4) == f(n) mod 4 for n from 1 to 100
counterexamples = []
for n in range(1, 101):
    fn = f(n)
    fn_plus_4 = f(n + 4)

    if fn % 4 != fn_plus_4 % 4:
        counterexamples.append((n, fn, fn_plus_4))

print(f"Found {len(counterexamples)} counterexamples to f(n+4) == f(n) mod 4 in the range n=1 to 100.")
if counterexamples:
    print("Counterexamples (n, f(n), f(n+4)):")
    for n, fn, fn_plus_4 in counterexamples:
        print(f"n={n}: f(n)={fn} ({fn % 4}), f(n+4)={fn_plus_4} ({fn_plus_4 % 4})")
else:
    print("No counterexamples found in the range n=1 to 100.")

